    def __init__(self):
        self.__dict__.update({'id': 'Solid244', 'source_dataset': 'MathVision', 'question': '$ABCDEFGH$ shown below is a right rectangular prism.  If the volume of pyramid $ABCH$ is 20, then what is the volume of $ABCDEFGH$?', 'answer': '120', 'answer_type': 'number', 'subject': 'SolidGeometry', 'source_key': 'test:2995', 'source_category': 'solid geometry', 'source_revision': '2837ddb3f13abaf6b3997c12d80753e5470bd46a'})
        self.query = self.question
        self.level = None
        self.scene_path = HERE / 'scenes/Solid244.json'

    def get_scene(self):
        return json.loads(self.scene_path.read_text(encoding='utf-8'))

    def draw(self, num=0, output_path=None):
        if output_path is None and isinstance(num, (str, Path)):
            output_path = num
        output = Path(output_path) if output_path else HERE.parents[1] / '.runtime/mathvision_redraw' / 'Solid244.png'
        spec = importlib.util.spec_from_file_location('mathvision_native_runtime', HERE / 'mathvision_renderers/shared_e4e003f51742cf00/runtime.py')
        runtime = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(runtime)
        return runtime.draw(HERE / 'mathvision_renderers/shared_e4e003f51742cf00/items/Solid244', HERE / 'mathvision_renderers/shared_e4e003f51742cf00/native', output, formal_scene=self.scene_path, original_image=HERE / '../originals/Solid244.jpg')

    def redraw(self, output_path=None):
        return self.draw(output_path=output_path)
